# ---------------------------------------------------------------- sky and sun
world = bpy.data.worlds.new("sky")
scene.world = world
world.use_nodes = True
WN = world.node_tree.nodes
WN["Background"].inputs["Color"].default_value = (0.72, 0.8, 0.9, 1) if DAY else (0.32, 0.38, 0.5, 1)
WN["Background"].inputs["Strength"].default_value = float(OPTS.get("sky", 1.0 if DAY else 1.3))
SUN_AZ, SUN_EL = math.radians(float(OPTS.get("sun_az", 300))), math.radians(float(OPTS.get("sun_el", 30)))
SUN_DIR = Vector((math.cos(SUN_AZ) * math.cos(SUN_EL), math.sin(SUN_AZ) * math.cos(SUN_EL), math.sin(SUN_EL)))
sun = bpy.data.lights.new("day_sun", "SUN")
sun.energy = float(OPTS.get("sun", 3.6))
sun.color = (1.0, 0.9, 0.76)
sun.angle = math.radians(1.5)
sun_ob = bpy.data.objects.new("day_sun", sun)
scene.collection.objects.link(sun_ob)
sun_ob.rotation_euler = SUN_DIR.to_track_quat("Z", "Y").to_euler()

# ---------------------------------------------------------------- shots
SHOT = {
    "aerial": dict(loc=vec("aerial_loc", (-3, -2.4, 18)), target=vec("aerial_at", (10.5, 12.9, 0.5)), lens=19, ev=-0.2),
    "street": dict(loc=vec("street_loc", (10.5, -6, 3.2)), target=vec("street_at", (10.5, 12.9, 1.6)), lens=24, ev=-0.2),
    "backyard": dict(loc=vec("backyard_loc", (10.5, 29, 4)), target=vec("backyard_at", (10.5, 15.9, 1.2)), lens=24, ev=-0.2),
    "interior": dict(loc=vec("interior_loc", (12.8, 12.9, 1.6)), target=vec("interior_at", (7.3, 10.95, 1.2)), lens=20, ev=-0.3),
}
EXPECTED_PARTS = 1342
print(f"built in {time.time() - t0:.1f} s, {len(K.PARTS)} parts (expected {EXPECTED_PARTS})")
if OPTS.get("blend"):
    bpy.ops.wm.save_as_mainfile(filepath=os.path.join(OUT, "demo-home.blend"))
for s in ([] if FILM else SHOTS):
    c = SHOT[s]
    scene.camera = camera(s, c["loc"], c["target"], c["lens"])
    scene.view_settings.exposure = float(OPTS.get(f"{s}_ev", c.get("ev", 0.0)))
    scene.render.filepath = os.path.join(OUT, f"render_{s}{OPTS.get('tag', '')}.png")
    t1 = time.time()
    bpy.ops.render.render(write_still=True)
    print(f"{s}: rendered in {time.time() - t1:.1f} s")
